return [
  { json: { number: 101, title: 'Login page crashes on wrong password', body: 'When I enter a wrong password the app shows a blank screen.', url: 'https://github.com/demo/app/issues/101' } },
  { json: { number: 102, title: 'Add dark mode to dashboard', body: 'Users want a dark theme option so the dashboard is easier to read at night.', url: 'https://github.com/demo/app/issues/102' } },
  { json: { number: 103, title: 'Typo in README installation section', body: 'The installation section has a spelling mistake in step 2.', url: 'https://github.com/demo/app/issues/103' } }
];

return $input.all().map((item) => {
  const i = item.json;
  const text = (i.title + ' ' + i.body).toLowerCase();

  let priority = 'low';
  if (/crash|error|security|fail|broken/.test(text)) priority = 'high';
  else if (/slow|bug|wrong/.test(text)) priority = 'medium';

  let type = 'task';
  if (/crash|error|bug|fail|broken|wrong/.test(text)) type = 'bug';
  else if (/typo|readme|docs|documentation/.test(text)) type = 'documentation';
  else if (/add|support|feature|improve/.test(text)) type = 'feature';

  const criteria = [
    'Problem is understood and reproduced',
    'Fix or change is implemented',
    'Tests or a manual check pass',
    'Issue is updated with the result'
  ];

  const aiReadyTask = [
    '### AI-ready task',
    '**Title:** ' + i.title,
    '**Type:** ' + type,
    '**Priority:** ' + priority,
    '**Description:** ' + i.body,
    '**Acceptance criteria:**',
    criteria.map((c) => '- [ ] ' + c).join('\n')
  ].join('\n');

  const telegramMessage = '🆕 Issue #' + i.number + '\n' + i.title + '\nType: ' + type + ' | Priority: ' + priority + '\n🔗 ' + i.url;

  return { json: { number: i.number, title: i.title, type: type, priority: priority, aiReadyTask: aiReadyTask, telegramMessage: telegramMessage } };
});
